        Recently Used (MRU) algorithm.

        Args:
            maxsize: The maximum number of results to store in the cache.
            typed: A boolean indicating whether the cached function returns
                typed or untyped results.

        Attributes:
            _cache: A dictionary of {Key: Value} pairs, where Key is the
                input arguments to the function and Value is the result
                returned by the function.
            _lru: A dictionary of {Key: datetime.datetime} pairs, where Key
                is the input arguments to the function and Value is the
                datetime object when the result was last accessed.
        """

        def __init__(self, maxsize=128, typed=False):
            self._cache = {}
            self._lru = {}
            self.maxsize = maxsize
            self.typed = typed

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = self.make_key(args, kwargs)
                if key in self._cache and func is not None:
                    self._move_to_front(key)
                    return self._cache[key]
                else:
                    result = func(*args, **kwargs)
                    self._cache[key] = result
                    self._lru[key] = datetime.datetime.now()
                    if len(self._cache) > self.maxsize:
                        self._trim_cache()
                    return result
            return wrapper

        def make_key(self, args, kwargs):
