def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of
    expressions applying absorption and negative absorption.
    """
    result = []
    for expr in args:
        for op in ["&", "|"]:
            for expr2 in args:
                if op == "&" and expr == expr2:
                    result.append(expr)
                elif op == "|" and not (expr == expr2):
                    result.append(expr)
    return result

