def find_path_type(path: str) -> str:
    """
    Returns a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        with open(path + "/0=*.nmd") as nmd_file:
            for line in nmd_file:
                if "ocfl_object" in line:
                    return "object"
                elif "ocfl_storage_root" in line:
                    return "root"
                elif "ocfl_file" in line:
                    return "file"
                else:
                    return "error"
    except FileNotFoundError:
        return "error"

